scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Compute n! mod mod
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

